head.script:

				var getType = function ( info ) {

					var rowIndex = info.rowIndex;
					var colIndex = info.colIndex;

					var returnInfo;
					var inputType = inputTypeList.getCellData( rowIndex, colIndex );

					switch(inputType) {
						case "radio": 
							returnInfo = {
								id : "dynamic_radio_" + rowIndex + "_" + colIndex,
								inputType : "radio",
								options : {
									groupName: "radio_"+rowIndex
								}

							}
							break;
						case "checkbox":
							returnInfo = {
								id : "dynamic_checkbox_" + rowIndex + "_" + colIndex,
								inputType : "checkbox",
								options : {

								}

							} 
							break;
						case "button":
							returnInfo = {
								id : "dynamic_button_" + rowIndex + "_" + colIndex,
								inputType : "button",
								options : {

								}

							}
							break;
						case "calendar": 
							returnInfo = {
								id : "dynamic_calendar_" + rowIndex + "_" + colIndex,
								inputType : "calendar",
								options : {
									viewType: "icon"
								}

							}
							break;
						case "image": 
							returnInfo = {
								id : "dynamic_image_" + rowIndex + "_" + colIndex,
								inputType : "image",
								options : {
									imageSrc : "s2.gif"
								}

							}
							break;
						case "link": 
							returnInfo = {
								id : "dynamic_link_" + rowIndex + "_" + colIndex,
								inputType : "link",
								options : {

								}

							}
							break;
						case "select": 
							returnInfo = {
								id : "dynamic_select_" + rowIndex + "_" + colIndex,
								inputType : "select",
								options : {
									viewType: "icon"
								},
								itemSet : {
									nodeset: "data:dataList3", 
									label: "label",
									value: "value"
								}

							}
							break;
						case "autoComplete": 
							returnInfo = {
								id : "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
								inputType : "autoComplete",
								options : {
									viewType: "icon"
								},
								itemSet : {
									nodeset: "data:dataList3", 
									label: "label",
									value: "value"
								}

							}
							break;
						case "checkcombobox": 
							returnInfo = {
								id : "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
								inputType : "checkcombobox",
								options : {
									viewType: "icon"
								},
								itemSet : {
									nodeset: "data:dataList3", 
									label: "label",
									value: "value"
								}

							}
							break;
						case "textarea":
							returnInfo = {
								id : "dynamic_textarea_" + rowIndex + "_" + colIndex,
								inputType : "textarea",
								options : {

								}

							}
							break;
						case "text": 
							returnInfo = {
								id : "dynamic_text_" + rowIndex + "_" + colIndex,
								inputType : "text",
								options : {

								}

							}
							break;
						case "textImage": 
							returnInfo = {
								id : "dynamic_textImage_" + rowIndex + "_" + colIndex,
								inputType : "textImage",
								options : {
									viewType: "icon",
									imageSrc : "s.gif",
									textAlign : "center"
								}

							}
							break;
					}

					return returnInfo;
				};		

			scwin.onpageload = function() {
				var itemArr = [
					{'label':'AA','value':'11'},
					{'label':'BB','value':'22'},
					{'label':'CC','value':'33'},
					{'label':'DD','value':'44'}
				];
				dataList3.setJSON(itemArr);

				var dataArr = [
				    "radio",
					"checkbox",
					"button",
					"calendar",
					"image",
					"link",
					"select",
					"autoComplete",
					"checkcombobox",
					"textarea",
					"text",
					"textImage"
				];

