":"calendar","col3":"s2.gif","col4":"link","col5":"select"},{"col1":"autoComplete","col2":"checkcombobox","col3":"textarea","col4":"text","col5":"textImage"},{"col1":"radio","col2":"checkbox","col3":"button","col4":"calendar","col5":"s2.gif"},{"col1":"link","col2":"select","col3":"autoComplete","col4":"checkcombobox","col5":"textarea"},{"col1":"text","col2":"textImage","col3":"radio","col4":"checkbox","col5":"button"},{"col1":"calendar","col2":"s2.gif","col3":"link","col4":"select","col5":"autoComplete"},{"col1":"checkcombobox","col2":"textarea","col3":"text","col4":"textImage","col5":"radio"},{"col1":"checkbox","col2":"button","col3":"calendar","col4":"s2.gif","col5":"link"},{"col1":"select","col2":"autoComplete","col3":"checkcombobox","col4":"textarea","col5":"text"},{"col1":"textImage","col2":"radio","col3":"checkbox","col4":"button","col5":"calendar"},{"col1":"s2.gif","col2":"link","col3":"select","col4":"autoComplete","col5":"checkcombobox"},{"col1":"textarea","col2":"text","col3":"textImage","col4":"radio","col5":"checkbox"},{"col1":"button","col2":"calendar","col3":"s2.gif","col4":"link","col5":"select"},{"col1":"autoComplete","col2":"checkcombobox","col3":"textarea","col4":"text","col5":"textImage"},{"col1":"radio","col2":"checkbox","col3":"button","col4":"calendar","col5":"s2.gif"},{"col1":"link","col2":"select","col3":"autoComplete","col4":"checkcombobox","col5":"textarea"},{"col1":"text","col2":"textImage","col3":"radio","col4":"checkbox","col5":"button"},{"col1":"calendar","col2":"s2.gif","col3":"link","col4":"select","col5":"autoComplete"}];
				dataList1.setJSON(jsonData);


	gridView1.setColumnVisible("col2", false);

			};

			scwin.onpageunload = function() {

			};


scwin.trigger1_onclick = function(e) {
